-- Manual, additive SQL Server migration; run after the Manager migration.
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.ADMIN_AUDIT_LOG','U') IS NULL
 CREATE TABLE dbo.ADMIN_AUDIT_LOG(id BIGINT IDENTITY PRIMARY KEY,actor_email VARCHAR(100) NOT NULL REFERENCES dbo.USERS(email),action_type VARCHAR(60) NOT NULL,entity_type VARCHAR(40) NOT NULL,entity_id NVARCHAR(100) NOT NULL,summary NVARCHAR(1000) NOT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.INVENTORY_MOVEMENTS','U') IS NULL
 CREATE TABLE dbo.INVENTORY_MOVEMENTS(id BIGINT IDENTITY PRIMARY KEY,store_id INT NOT NULL,variant_id BIGINT NOT NULL,old_quantity INT NOT NULL,quantity_delta INT NOT NULL,new_quantity INT NOT NULL,movement_type VARCHAR(30) NOT NULL,reason NVARCHAR(1000) NOT NULL,reference_type VARCHAR(40) NULL,reference_id BIGINT NULL,performed_by VARCHAR(100) NOT NULL REFERENCES dbo.USERS(email),created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT FK_ADMIN_MOVEMENT_INVENTORY FOREIGN KEY(store_id,variant_id) REFERENCES dbo.STORE_INVENTORY(store_id,variant_id),CONSTRAINT CK_ADMIN_MOVEMENT CHECK(old_quantity>=0 AND new_quantity>=0 AND CONVERT(BIGINT,old_quantity)+quantity_delta=new_quantity AND movement_type IN('RESTOCK','MANUAL_ADJUSTMENT','CORRECTION','RETURN')));
IF OBJECT_ID('dbo.PAYMENT_VERIFICATIONS','U') IS NULL
 CREATE TABLE dbo.PAYMENT_VERIFICATIONS(id BIGINT IDENTITY PRIMARY KEY,payment_id BIGINT NOT NULL REFERENCES dbo.PAYMENTS(id),reported_by VARCHAR(100) NOT NULL REFERENCES dbo.USERS(email),reported_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),status VARCHAR(20) NOT NULL DEFAULT 'PENDING',reviewed_by VARCHAR(100) NULL REFERENCES dbo.USERS(email),reviewed_at DATETIME2 NULL,review_note NVARCHAR(1000) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT CK_ADMIN_VERIFICATION CHECK(status IN('PENDING','CONFIRMED','REJECTED')));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.PAYMENT_VERIFICATIONS') AND name='UX_ADMIN_PENDING_VERIFICATION')
 CREATE UNIQUE INDEX UX_ADMIN_PENDING_VERIFICATION ON dbo.PAYMENT_VERIFICATIONS(payment_id) WHERE status='PENDING';
IF COL_LENGTH('dbo.CATALOG_CHANGE_REQUESTS','review_note') IS NULL
 ALTER TABLE dbo.CATALOG_CHANGE_REQUESTS ADD review_note NVARCHAR(1000) NULL;
IF COL_LENGTH('dbo.PROMOTIONS','scope') IS NULL
 ALTER TABLE dbo.PROMOTIONS ADD scope VARCHAR(20) NOT NULL CONSTRAINT DF_ADMIN_PROMOTION_SCOPE DEFAULT 'PRODUCT' WITH VALUES;
IF COL_LENGTH('dbo.PROMOTIONS','priority') IS NULL
 ALTER TABLE dbo.PROMOTIONS ADD priority INT NOT NULL CONSTRAINT DF_ADMIN_PROMOTION_PRIORITY DEFAULT 0 WITH VALUES;
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name='CK_ADMIN_PROMOTION_SCOPE')
 EXEC('ALTER TABLE dbo.PROMOTIONS ADD CONSTRAINT CK_ADMIN_PROMOTION_SCOPE CHECK(scope IN(''GLOBAL'',''STORE'',''CATEGORY'',''BRAND'',''PRODUCT'',''VARIANT''))');
IF OBJECT_ID('dbo.STORE_PROMOTIONS','U') IS NULL
 CREATE TABLE dbo.STORE_PROMOTIONS(promotion_id INT NOT NULL REFERENCES dbo.PROMOTIONS(id),store_id INT NOT NULL REFERENCES dbo.STORES(store_id),PRIMARY KEY(promotion_id,store_id));
IF OBJECT_ID('dbo.CATEGORY_PROMOTIONS','U') IS NULL
 CREATE TABLE dbo.CATEGORY_PROMOTIONS(promotion_id INT NOT NULL REFERENCES dbo.PROMOTIONS(id),category_id INT NOT NULL REFERENCES dbo.CATEGORIES(id),PRIMARY KEY(promotion_id,category_id));
IF OBJECT_ID('dbo.BRAND_PROMOTIONS','U') IS NULL
 CREATE TABLE dbo.BRAND_PROMOTIONS(promotion_id INT NOT NULL REFERENCES dbo.PROMOTIONS(id),brand_id INT NOT NULL REFERENCES dbo.BRANDS(id),PRIMARY KEY(promotion_id,brand_id));
IF OBJECT_ID('dbo.VARIANT_PROMOTIONS','U') IS NULL
 CREATE TABLE dbo.VARIANT_PROMOTIONS(promotion_id INT NOT NULL REFERENCES dbo.PROMOTIONS(id),variant_id BIGINT NOT NULL REFERENCES dbo.PRODUCT_VARIANTS(id),PRIMARY KEY(promotion_id,variant_id));
IF COL_LENGTH('dbo.COUPONS','per_user_limit') IS NULL
 ALTER TABLE dbo.COUPONS ADD per_user_limit INT NULL;
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name='CK_ADMIN_COUPON_USER_LIMIT')
 EXEC('ALTER TABLE dbo.COUPONS ADD CONSTRAINT CK_ADMIN_COUPON_USER_LIMIT CHECK(per_user_limit IS NULL OR per_user_limit>0)');
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.INVENTORY_MOVEMENTS') AND name='IX_ADMIN_MOVEMENTS')
 CREATE INDEX IX_ADMIN_MOVEMENTS ON dbo.INVENTORY_MOVEMENTS(store_id,variant_id,created_at DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.ADMIN_AUDIT_LOG') AND name='IX_ADMIN_AUDIT')
 CREATE INDEX IX_ADMIN_AUDIT ON dbo.ADMIN_AUDIT_LOG(created_at DESC);
COMMIT;
